Batched Writes & Transactions:
import { writeBatch, doc } from 'firebase/firestore';

// Batch write (atomic, up to 500 ops)
const batch = writeBatch(db);
batch.set(doc(db, 'users', 'bob'), { name: 'Bob' });
batch.update(doc(db, 'users', 'alice'), { balance: 500 });
batch.delete(doc(db, 'posts', 'old-post'));
await batch.commit();

// Transaction
import { runTransaction } from 'firebase/firestore';
await runTransaction(db, async (transaction) => {
  const ref = doc(db, 'counters', 'pageViews');
  const snap = await transaction.get(ref);
  const count = (snap.data()?.count || 0) + 1;
  transaction.set(ref, { count });
});

