Security Rules Deep:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /posts/{postId} {
      // Create: validate data shape
      allow create: if request.auth != null
        && request.resource.data.keys().hasAll(['title', 'body', 'authorId'])
        && request.resource.data.title is string
        && request.resource.data.title.size() > 0
        && request.resource.data.title.size() <= 500
        && request.resource.data.authorId == request.auth.uid;

      // Update: prevent field changes
      allow update: if request.auth != null
        && request.resource.data.authorId == resource.data.authorId
        && request.resource.data.title == resource.data.title; // can't change title

      // Delete: owner or admin
      allow delete: if request.auth != null && (
        resource.data.authorId == request.auth.uid
        || request.auth.token.role == 'admin'
      );
    }
  }
}

