// Firestore trigger
export const onNewUser = onDocumentCreated('users/{userId}', async (event) => {
  const user = event.data?.data();
  if (!user) return;

  // Send welcome email
  await sendWelcomeEmail(user.email);

  // Create user settings document
  await event.data.ref.collection('settings').doc('preferences').set({
    theme: 'light',
    notifications: true,
    createdAt: admin.firestore.FieldValue.serverTimestamp()
  });
});

// HTTP function
export const generateReport = onRequest({ cors: true, maxInstances: 10 }, async (req, res) => {
  const { userId } = req.query;
  if (!userId) { res.status(400).send('Missing userId'); return; }

  const report = await generateUserReport(userId as string);
  res.json(report);
});

// Scheduled function (daily)
export const cleanupOldData = onSchedule('0 3 * * *', async () => {
  const cutoff = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000);
  const oldLogs = await db.collection('logs')
    .where('createdAt', '<', cutoff)
    .limit(500)
    .get();

  const batch = db.batch();
  oldLogs.docs.forEach(doc => batch.delete(doc.ref));
  await batch.commit();
});
